import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';

import { VisualizarVotacaoService } from '../../../../services/visualizar-votacao.service';

@Component({
  selector: 'app-votacao-escolha-unica',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './votacao-escolha-unica.component.html',
  styleUrls: ['./votacao-escolha-unica.component.scss']
})
export class VotacaoEscolhaUnicaComponent {

  @Input({ required: true })
  votacao!: any;

  @Output()
  votoConcluido = new EventEmitter<void>();

  candidatoSelecionado?: number;

  enviando = false;
  votoRegistrado = false;
  erro = '';

  constructor(
    private readonly visualizarVotacaoService: VisualizarVotacaoService
  ) { }

  selecionar(votacaoCandidatoId: number): void {
    if (this.votoRegistrado) {
      return;
    }

    this.candidatoSelecionado = votacaoCandidatoId;
  }

  confirmarVoto(): void {

    if (!this.candidatoSelecionado || this.votoRegistrado) {
      return;
    }

    this.enviando = true;
    this.erro = '';

    this.visualizarVotacaoService
      .votar(
        this.votacao.id,
        {
          conselhoId: null,
          itens: [
            {
              votacaoCandidatoId: this.candidatoSelecionado,
              escolhido: true,
              nota: null,
              criterios: []
            }
          ]
        }
      )
      .subscribe({
        next: () => {
          this.votoRegistrado = true;
          this.enviando = false;
          this.votoConcluido.emit();
        },
        error: (error) => {
          this.erro =
            error?.error?.message ||
            'Erro ao registrar voto.';

          this.enviando = false;
        }
      });
  }
}
