import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  FormBuilder,
  ReactiveFormsModule,
  Validators
} from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { jwtDecode } from 'jwt-decode';

import {
  PublicoAvaliacao,
  VisualizarVotacaoService,
  VotacaoResumo
} from '../../services/visualizar-votacao.service';
import { VotacaoEscolhaUnicaComponent } from './components/votacao-escolha-unica/votacao-escolha-unica.component';
import { VotacaoAvaliacaoComponent } from './components/votacao-avaliacao/votacao-avaliacao.component';

@Component({
  selector: 'app-visualizar-votacao',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    VotacaoEscolhaUnicaComponent,
    VotacaoAvaliacaoComponent
  ],
  templateUrl: './visualizar-votacao.component.html',
  styleUrls: ['./visualizar-votacao.component.scss']
})
export class VisualizarVotacaoComponent implements OnInit {

  votacao: any;
  votacaoSelecionada?: VotacaoResumo;
  votacoesVigentes: VotacaoResumo[] = [];
  publicoAlvo: PublicoAvaliacao = 'PUBLICO';
  votacaoIdRota?: number;

  autenticado = false;
  carregando = false;
  carregandoVotacoes = false;
  autenticando = false;
  votoRegistrado = false;

  erroAcesso = '';
  erroCarregamento = '';
  erroVotacoes = '';

  formCodigo = this.fb.nonNullable.group({
    codigo: [
      '',
      [
        Validators.required,
        Validators.pattern(/^[A-Za-z0-9]{6}$/)
      ]
    ]
  });

  constructor(
    private readonly fb: FormBuilder,
    private readonly route: ActivatedRoute,
    private readonly visualizarVotacaoService: VisualizarVotacaoService
  ) {}

  ngOnInit(): void {
    this.publicoAlvo = this.route.snapshot.data['publicoAlvo'] === 'AVALIADOR'
      ? 'AVALIADOR'
      : 'PUBLICO';

    const idParam = Number(this.route.snapshot.paramMap.get('id'));
    if (Number.isInteger(idParam) && idParam > 0) {
      this.votacaoIdRota = idParam;
    }

    this.autenticado = this.votanteAutenticado();

    if (this.autenticado) {
      this.iniciarFluxoAutenticado();
    }
  }

  autenticarVotante(): void {
    if (this.formCodigo.invalid) {
      this.formCodigo.markAllAsTouched();
      return;
    }

    this.autenticando = true;
    this.erroAcesso = '';

    const codigo = this.formCodigo.controls.codigo.value.trim().toUpperCase();

    this.visualizarVotacaoService
      .autenticarVotante(codigo)
      .subscribe({
        next: (response) => {
          localStorage.setItem('votante_token', response.token);
          localStorage.setItem('votante_usuario', JSON.stringify(response.usuario));
          localStorage.removeItem('votante_votacao_id');

          this.autenticado = true;
          this.autenticando = false;
          this.iniciarFluxoAutenticado();
        },
        error: (error) => {
          this.erroAcesso =
            error?.error?.message ||
            'Código inválido ou não autorizado.';

          this.autenticando = false;
        }
      });
  }

  carregarVotacoesVigentes(): void {
    this.carregandoVotacoes = true;
    this.erroVotacoes = '';
    this.votacao = undefined;
    this.votacaoSelecionada = undefined;

    this.visualizarVotacaoService
      .listarVotacoes()
      .subscribe({
        next: (response) => {
          this.votacoesVigentes = (response || [])
            .filter(votacao => this.estaVigente(votacao))
            .sort((a, b) =>
              new Date(a.dataFim).getTime() - new Date(b.dataFim).getTime()
            );

          this.carregandoVotacoes = false;
        },
        error: (error) => {
          this.erroVotacoes =
            error?.error?.message ||
            'Erro ao carregar as votações vigentes.';
          this.carregandoVotacoes = false;
        }
      });
  }

  selecionarVotacao(votacao: VotacaoResumo): void {
    this.votacaoSelecionada = votacao;
    localStorage.setItem('votante_votacao_id', String(votacao.id));
    this.carregarVotacao(Number(votacao.id));
  }

  voltarParaVotacoes(): void {
    this.votacao = undefined;
    this.votacaoSelecionada = undefined;
    this.erroCarregamento = '';
    localStorage.removeItem('votante_votacao_id');
  }

  carregarVotacao(id: number): void {
    this.carregando = true;
    this.erroCarregamento = '';

    this.visualizarVotacaoService
      .get(id, this.publicoAlvo)
      .subscribe({
        next: (response) => {
          this.votacao = response;
          this.carregando = false;
        },
        error: (error) => {
          this.erroCarregamento =
            error?.error?.message ||
            'Erro ao carregar a votação.';

          this.carregando = false;
        }
      });
  }

  onVotoRegistrado(): void {
    this.votoRegistrado = true;
    this.votacao = undefined;
    localStorage.removeItem('votante_votacao_id');
  }

  finalizar(): void {
    this.limparSessaoVotante();
    this.autenticado = false;
    this.votoRegistrado = false;
    this.votacoesVigentes = [];
    this.votacaoSelecionada = undefined;
    this.formCodigo.reset({ codigo: '' });
  }

  fieldError(): string {
    const control = this.formCodigo.controls.codigo;

    if (!control.touched || !control.errors) {
      return '';
    }

    if (control.errors['required']) {
      return 'Informe o código de votação.';
    }

    if (control.errors['pattern']) {
      return 'O código deve ter 6 caracteres alfanuméricos.';
    }

    return 'Código inválido.';
  }

  private iniciarFluxoAutenticado(): void {
    if (this.votacaoIdRota) {
      this.carregarVotacao(this.votacaoIdRota);
      return;
    }

    this.carregarVotacoesVigentes();
  }

  private estaVigente(votacao: VotacaoResumo): boolean {
    const agora = Date.now();
    const inicio = new Date(votacao.dataInicio).getTime();
    const fim = new Date(votacao.dataFim).getTime();

    if (Number.isNaN(inicio) || Number.isNaN(fim)) {
      return false;
    }

    return inicio <= agora && agora <= fim;
  }

  private votanteAutenticado(): boolean {
    const token = localStorage.getItem('votante_token');

    if (!token) {
      return false;
    }

    try {
      const decoded: any = jwtDecode(token);
      const now = Math.floor(Date.now() / 1000);

      if (decoded.exp && decoded.exp < now) {
        this.limparSessaoVotante();
        return false;
      }

      return true;
    } catch {
      this.limparSessaoVotante();
      return false;
    }
  }

  private limparSessaoVotante(): void {
    localStorage.removeItem('votante_token');
    localStorage.removeItem('votante_usuario');
    localStorage.removeItem('votante_votacao_id');
  }
}
